#define USB_TIMEOUT_DEFAULT     20000
#define USB_TIMEOUT_LONG        60000

static inline int get_timeout(PTP_USB* ptp_usb) {
    if (FLAG_LONG_TIMEOUT(ptp_usb)) {
        return USB_TIMEOUT_LONG;
    }
    return USB_TIMEOUT_DEFAULT;
}

