83: // Strip the trailing newline from fgets().
84: static char *fgets_strip(char **str, int num, FILE *stream)
85: {
86: 	*str = (char*)malloc(num);
87: 	char* result = *str;
88: 	if (fgets(result, num, stream) != NULL)
89: 	{
90: 		size_t newlen = strlen(result);
91: 
92: 		if (newlen > 0 && (result[newlen - 1] == '\n' || result[newlen - 1] == '\r'))
93: 		{
94: 			result[newlen - 1] = '\0';
95: 			if (newlen > 1 && result[newlen - 2] == '\r')
96: 			{
97: 				result[newlen - 2] = '\0';
98: 			}
99: 		}
100: 
101: 		return result;
102: 	}
103: 
104: 	return NULL;
105: }
