107: static char *hex_to_bytes(char *hex, size_t len)
108: {
109: 	if (len % 2)
110: 		return NULL;
111: 
112: 	char *bytes = malloc(len / 2);
113: 	unsigned int u;
114: 	unsigned int i = 0;
115: 
116: 	while (i < len && sscanf(hex + i, "%2x", &u) == 1)
117: 	{
118: 		bytes[i / 2] = u;
119: 		i += 2;
120: 	}
121: 
122: 	return bytes;
